function divide(a, b) {
  if (b === 0) throw new Error('divide by zero');
  return a / b;
}
function getAge(birthYears, people) {
  return divide(birthYears, people);
}
function loadUser() {
  return getAge(60, 0);
}
function main() {
  try {
    loadUser();
  } catch (e) {
    console.log('caught: ' + e.message);
  }
}
main();

